import{_ as e,a,c as t,ac as r}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Rust 工具链：环境准备与日常开发","description":"从检查工具链和创建项目开始，建立格式、编译检查、Clippy、测试与依赖管理流程。","frontmatter":{"title":"Rust 工具链：环境准备与日常开发","description":"从检查 rustup、创建 Cargo 项目开始，建立格式检查、静态检查、测试、构建与依赖管理的日常流程。","sources":[{"repository":"jekyall_blog","file":"_posts/Language/rust/2023-11-06-rust-tools.md","date":"Mon Nov 06 2023 11:58:36 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"rust","title":"Rust","link":"/topics/rust/"}],"kind":"知识专题","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"Rust 系统学习","summary":"从检查工具链和创建项目开始，建立格式、编译检查、Clippy、测试与依赖管理流程。","status":"active","related":[{"title":"Rust 操作与命令","link":"/programming/rust/plus/ecosystem/rust-general-general","kind":"排错","scope":"general","audience":"general"},{"title":"Rust 操作与命令 · 安装命令工具与发布软件包","link":"/programming/rust/plus/ecosystem/rust-general-general-part-04","kind":"排错","scope":"general","audience":"general"},{"title":"Rust 操作与命令 · 编译、运行、测试与基准测量至阅读文档与命令帮助","link":"/programming/rust/plus/ecosystem/rust-general-general-part-03","kind":"排错","scope":"general","audience":"general"},{"title":"Rust 操作与命令 · 查看、安装与更新 Rust 工具链至创建和定位 Cargo 项目","link":"/programming/rust/plus/ecosystem/rust-general-general-part-01","kind":"排错","scope":"general","audience":"general"},{"title":"Rust 操作与命令 · 选择依赖、更新锁文件与准备离线构建至格式化、静态检查与自动修复","link":"/programming/rust/plus/ecosystem/rust-general-general-part-02","kind":"排错","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Rust 系统学习：从基础语法到工程实践","link":"/programming/rust/base/basic/rust"}},"hashRedirects":{"rust-开发工具参考":"/programming/rust/plus/ecosystem/rust-tools#start","cargo":"/programming/rust/plus/ecosystem/rust-tools#first-project","cargo-clippy":"/programming/rust/plus/ecosystem/rust-tools#workflow","cargo-fmt":"/programming/rust/plus/ecosystem/rust-tools#workflow","cargo-miri":"/programming/rust/plus/ecosystem/rust-tools#advanced-tools","clippy-driver":"/programming/rust/plus/ecosystem/rust-tools#workflow","rls-rust-language-server":"/programming/rust/plus/ecosystem/rust-tools#diagnostics","rust-gdb-gnu-debugger":"/programming/rust/plus/ecosystem/rust-tools#diagnostics","rust-gdbgui":"/programming/rust/plus/ecosystem/rust-tools#diagnostics","rust-lldb-llvm-debugger":"/programming/rust/plus/ecosystem/rust-tools#diagnostics","rustc":"/programming/rust/plus/ecosystem/rust-tools#start","rustdoc":"/programming/rust/plus/ecosystem/rust-tools#diagnostics","rustfmt":"/programming/rust/plus/ecosystem/rust-tools#workflow","rustup":"/programming/rust/plus/ecosystem/rust-tools#start"},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Rust 系统学习：从基础语法到工程实践","link":"/programming/rust/base/basic/rust"}},"headers":[],"relativePath":"programming/rust/plus/ecosystem/rust-tools.md","filePath":"programming/rust/plus/ecosystem/rust-tools.md"}'),i={name:"programming/rust/plus/ecosystem/rust-tools.md"};function o(n,s,l,p,d,c){return a(),t("div",null,[...s[0]||(s[0]=[r(`<h1 id="rust-工具链-环境准备与日常开发" tabindex="-1">Rust 工具链：环境准备与日常开发 <a class="header-anchor" href="#rust-工具链-环境准备与日常开发" aria-label="Permalink to &quot;Rust 工具链：环境准备与日常开发&quot;">​</a></h1><p><span id="rust-tools"></span></p><p>这是 <a href="/programming/rust/base/basic/rust">Rust 系统学习</a>的第一步。完成本页后，应能创建项目、运行测试，并知道日常检查失败时从哪里排查。</p><p><span id="rust-开发工具参考"></span><span id="rustc"></span><span id="rustup"></span></p><h2 id="start" tabindex="-1">安装与确认工具链 <a class="header-anchor" href="#start" aria-label="Permalink to &quot;安装与确认工具链 {#start}&quot;">​</a></h2><p><code>rustup</code> 管理工具链和组件，<code>rustc</code> 编译 Rust 源码，<code>cargo</code> 管理项目、依赖和构建。安装前先看项目是否提供 <code>rust-toolchain.toml</code> 或 <code>rust-toolchain</code>；已有项目应优先使用其规定的版本。</p><p>新环境按<a href="https://doc.rust-lang.org/book/ch01-01-installation.html" target="_blank" rel="noopener noreferrer">官方安装说明</a>安装。Windows 的 MSVC 工具链还需要相应的 C++ 构建工具；Linux、macOS 也需要平台要求的链接器。安装结束后重新打开终端检查：</p><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>如果找不到命令，先检查安装是否完成、终端是否继承了新的 <code>PATH</code>。如果编译时找不到 linker，应检查系统构建工具，而不是重复下载 Rust。</p><p>对于没有版本约束的个人练习，可安装稳定工具链及常用组件：</p><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> toolchain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> component</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rustfmt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clippy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --toolchain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable</span></span></code></pre></div><p>安装不等于切换：回到练习目录运行 <code>rustup show</code>，确认当前选中的工具链。若没有项目版本约束但当前选中的是其他工具链，可在该练习目录运行 <code>rustup override set stable</code>；已有项目仍按它的版本配置执行。也可以用 <code>cargo +stable run</code> 只为单次命令选择工具链。参见<a href="https://rust-lang.github.io/rustup/overrides.html" target="_blank" rel="noopener noreferrer">工具链选择与覆盖规则</a>。</p><p>项目的 edition 是 <code>Cargo.toml</code> 中的语言兼容性选项，不等于编译器版本；不同 edition 的 crate 可以协作。使用新 edition 前要检查其最低编译器版本。参见<a href="https://doc.rust-lang.org/edition-guide/editions/index.html" target="_blank" rel="noopener noreferrer">edition 指南</a>。</p><p><span id="cargo"></span></p><h2 id="first-project" tabindex="-1">创建并运行第一个项目 <a class="header-anchor" href="#first-project" aria-label="Permalink to &quot;创建并运行第一个项目 {#first-project}&quot;">​</a></h2><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello_rust</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello_rust</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p><code>src/main.rs</code> 是默认二进制入口，<code>Cargo.toml</code> 描述 package 与依赖。<code>cargo run</code> 会在需要时构建，然后运行程序。创建库项目使用 <code>cargo new my_library --lib</code>。</p><p>新建的二进制示例尚未定义测试，<code>cargo test</code> 显示零个测试也属正常；看到它成功，只能说明当前测试构建和测试运行完成，不能说明 <code>main</code> 的输出已被断言验证。接着阅读基础主线的断言与测试说明。</p><p>先让生成的示例工作，再开始替换为<a href="/programming/rust/base/basic/rust#syntax">基础语法示例</a>。这样可以区分环境问题和代码问题。参见<a href="https://doc.rust-lang.org/book/ch01-03-hello-cargo.html" target="_blank" rel="noopener noreferrer">Hello, Cargo!</a>。</p><p><span id="cargo-clippy"></span><span id="cargo-fmt"></span><span id="clippy-driver"></span><span id="rustfmt"></span></p><h2 id="workflow" tabindex="-1">每次修改后的检查顺序 <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;每次修改后的检查顺序 {#workflow}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>能证明什么</th></tr></thead><tbody><tr><td><code>cargo fmt --check</code></td><td>检查格式</td><td>格式符合 rustfmt；不会自动改写文件</td></tr><tr><td><code>cargo check</code></td><td>快速检查当前默认目标</td><td>检查代码能否通过相应编译阶段，不生成最终可执行文件</td></tr><tr><td><code>cargo clippy --all-targets</code></td><td>检查库、二进制、测试等目标</td><td>提供额外 lint 建议，不替代测试</td></tr><tr><td><code>cargo test</code></td><td>编译并执行测试</td><td>验证被测试覆盖的行为</td></tr><tr><td><code>cargo build --release</code></td><td>构建发布配置</td><td>完成当前目标的优化构建，不代表所有行为已测试</td></tr></tbody></table><p>格式不符时运行 <code>cargo fmt</code> 并检查差异。工作区项目通常还要选择 <code>--workspace</code>；features、目标平台和示例是否需要纳入检查，服从项目已有 CI 约定。不要为了让一条命令“覆盖更多”盲目启用互相不兼容的所有 features。</p><p><a href="https://doc.rust-lang.org/cargo/commands/cargo-check.html" target="_blank" rel="noopener noreferrer"><code>cargo check</code></a>与<a href="https://doc.rust-lang.org/cargo/commands/cargo-test.html" target="_blank" rel="noopener noreferrer"><code>cargo test</code></a>有不同目标和构建行为；快速检查通过以后仍应运行项目测试。<a href="https://doc.rust-lang.org/clippy/usage.html" target="_blank" rel="noopener noreferrer">Clippy 使用说明</a>解释了目标选择和 lint 配置。</p><h2 id="dependencies" tabindex="-1">理解依赖与锁文件 <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;理解依赖与锁文件 {#dependencies}&quot;">​</a></h2><p><code>Cargo.toml</code> 的版本要求说明允许哪些依赖版本；<code>Cargo.lock</code> 记录这次解析选择的具体版本。遵循项目约定提交和更新锁文件，避免一次无关修改夹带整批依赖变化。</p><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tree</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dependency_name</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p><code>dependency_name</code> 需要换成真实依赖名称。<code>cargo tree</code> 查看实际依赖关系，<code>cargo update -p</code> 在清单约束内更新指定 package；<code>--locked</code> 要求锁文件保持不变，若需要变动则失败。它不表示离线运行，也不保证本地已有全部依赖。参见<a href="https://doc.rust-lang.org/cargo/guide/cargo-toml-vs-cargo-lock.html" target="_blank" rel="noopener noreferrer">锁文件</a>和<a href="https://doc.rust-lang.org/cargo/commands/cargo-update.html" target="_blank" rel="noopener noreferrer"><code>cargo update</code></a>。</p><p>下载确实受限时，应先确认是 Rust 工具链分发还是 Cargo registry 获取失败，再按组织要求配置；不要混淆 rustup 的下载地址和 Cargo 的 registry。Cargo 的项目与用户级配置位置见<a href="https://doc.rust-lang.org/cargo/reference/config.html" target="_blank" rel="noopener noreferrer">配置参考</a>。</p><p><span id="rls-rust-language-server"></span><span id="rust-gdb-gnu-debugger"></span><span id="rust-gdbgui"></span><span id="rust-lldb-llvm-debugger"></span><span id="rustdoc"></span></p><h2 id="diagnostics" tabindex="-1">文档、编辑器与诊断 <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;文档、编辑器与诊断 {#diagnostics}&quot;">​</a></h2><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --open</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --explain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> E0382</span></span></code></pre></div><p>第一条为项目与依赖生成 API 文档并打开；第二条解释一个具体错误码，需替换成实际诊断中的代码。遇到编译错误先读第一条与自身代码相关的诊断，确认文件位置、期望类型和实际类型，再看编译器建议；不要连续套用建议而忽略所有权设计。</p><p>编辑器使用 <a href="https://rust-analyzer.github.io/" target="_blank" rel="noopener noreferrer">rust-analyzer</a> 提供补全、跳转和诊断。调试则取决于平台与所装调试器，可使用 GDB / LLDB 或对应的编辑器集成；Clippy 日常通过 <code>cargo clippy</code> 运行。</p><p><span id="cargo-miri"></span></p><h2 id="advanced-tools" tabindex="-1">什么时候再看 nightly 和 Miri <a class="header-anchor" href="#advanced-tools" aria-label="Permalink to &quot;什么时候再看 nightly 和 Miri {#advanced-tools}&quot;">​</a></h2><p>学习本文与基础主线不需要 nightly。Miri 可检查执行路径上的若干未定义行为，适合深入研究 unsafe 等场景；它不能证明整个程序没有问题。Miri 通常通过 nightly 工具链安装和运行，应按 <a href="https://github.com/rust-lang/miri#readme" target="_blank" rel="noopener noreferrer">Miri 项目说明</a>选择组件与命令，不能假定 <code>cargo miri</code> 已经随 stable 可用。</p><p>旧 <code>gitbook</code> 系列包含历史基准测试、编译器插件与 feature gate 写法，查用前需核对对应版本。正式发布 crate 是单独的发布流程；日常学习与本地验证无需运行 <code>cargo publish</code>。</p>`,38)])])}const u=e(i,[["render",o]]);export{h as __pageData,u as default};
